steps.sampleSolution:
type Enviador interface {
    Enviar(msg string) error
}
type SMS struct { Numero string }

func (s SMS) Enviar(msg string) error {
    if s.Numero == "" {
        return fmt.Errorf("numero vazio")
    }
    return nil
}
